$steps += @{ Name = 'T21 Import the Mail solution r1'; Dir = 'T21'; File = '90161Z-T21-probe-mail-r1.zip'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You import the solution "90-161.Z probe Mail" and select Done. The import may be refused on this tenant: a refusal is a valid result. About 4 minutes (estimate).'; Kind = 'guide'; Guide = @('1. Select "Open in browser". Power Automate opens; sign in with your CAC if asked.', '2. Select Solutions (under More if it is not shown), then Import solution > Browse.', '3. In the File name box, press Ctrl+V (the file path is on the clipboard), select Open, then Next.', '4. Connections: select your existing connection for SharePoint; create one for Mail.', '5. Microsoft says the Mail connector is not in DoD. If the page cannot find it, that is the refusal.', '6. Environment variables: "1 Site URL": the test site address. "2 Alert e-mail": your own work e-mail address.', '7. Keep all other values. Select Import and wait for "Successfully imported" (1 to 3 minutes, estimate).', '8. Open the solution. The flow "90161Z T21 Probe Mail Notify r1" must read On. If one reads Off, turn it on.', '9. Return to RADE and select "Done: imported".', 'If the import is refused: that is a result. Select "Download log file", type the first red error line (no names) below, then select "It failed".'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-mail-imported.txt'; Estimate = 240; DoneText = 'Done: imported'; DoneLog = 'Confirmed by you: imported.'; Makes = @(@{ kind = 'solution'; name = '90-161.Z probe Mail (1 flow)' }); After = @('T21 Make the probe list and library r1'); Optional = $false; Help = 'Send the results as they are; the import log step reads the log if you downloaded it.' }
