$steps += @{ Name = 'T21 AI Builder look r1'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Test T6, way a. You look whether Power Automate offers an AI Builder action on this tenant, and answer 1 question. Nothing is saved. About 3 minutes (estimate).'; Kind = 'guide'; Guide = @('1. Select "Open in browser". In Power Automate select Create > Instant cloud flow > Skip (no name is needed).', '2. Select the + under the trigger (or New step). In the search box type: AI Builder', '3. Look for the action "Run a prompt" (older name: "Create text with GPT using a prompt").', '4. If it is offered: select it, open its Prompt list, and look whether a prompt such as "Summarize text" can be chosen.', '5. Close the browser tab without saving (select Leave if asked).', '6. Return to RADE, select "Done: I looked" and answer the question.', 'If Power Automate does not open: select "It failed" and type what you see (no names or addresses).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-aib-looked.txt'; Estimate = 180; DoneText = 'Done: I looked'; DoneLog = 'Confirmed by you: I looked.'; Makes = @(); After = @(); Optional = $false; Help = ''; Answers = @(@{ Key = 't6-aibuilder'; Prompt = 'What did Power Automate offer for AI Builder?'; Kind = 'pick'; Choices = @('Run a prompt, and a prompt can be chosen', 'Run a prompt, but no prompt or an error', 'Other AI Builder actions only', 'No AI Builder action') }) }
$steps += @{ Name = 'T21 Run the flow tests r1'; Dir = 'T21'; File = '90161Z-T21-probe-r1.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = '-Part Run'; Note = 'Signs in (CAC). Starts the probe flows and waits up to 14 minutes: file conversion (T3, T5), fields (T6), 4 test e-mails read back by a flow (T9). Do not open Outlook. About 15 minutes (estimate).'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 900; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Import the probe solution r1'); Optional = $false; Help = 'Send the results as they are. A FAILED line is a result of the probe, not a fault of the round.' }
$steps += @{ Name = 'T21 Build the test app r1'; Dir = 'T21'; File = '90161Z-T21-probe-app-r1.txt'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You make one blank canvas app and paste 6 small code blocks. A plain test screen, not a design. Microsoft has no supported import for an app built outside Power Apps. About 15 minutes (estimate).'; Kind = 'guide'; Guide = @('1. Open the code file: press Windows key + R, press Ctrl+V (the file path is on the clipboard), then Enter. Keep Notepad open.', '2. Select "Open in browser". Power Apps opens; sign in with your CAC if asked.', '3. Select Create > Blank app > Blank canvas app. Name: 90161Z T21 Probe r1. Format: Tablet. Select Create.', '4. On the left select Data > Add data > SharePoint. Paste the test site address, tick "90161Z Probe" and "90161Z Probe Files", select Connect.', '5. Select Add data again, type Office 365 Users, and select it.', '6. On the left select Power Automate (under the three dots if it is not shown) > Add flow > "90161Z T21 Probe App r1".', '7. Select Insert > Edit form. Data source: "90161Z Probe". Keep the fields Title and Attachments. Drag the form to the lower right.', '8. In Tree view, double-click the name of the form and type: frmProbe', '9. Set the form as the part "BY HAND for block 6" in the file says, items 4 to 6 (3 short formulas).', '10. In Notepad, copy block 1 (the lines between its 2 marker lines). In Tree view, right-click Screen1 and select Paste code.', '11. Do step 10 again for blocks 2 to 6. If a block is refused: use the part "BY HAND" under that block in the file, then go on.', '12. Select Save (Ctrl+S), then Publish > Publish this version.', '13. Return to RADE, select "Done: app built" and answer the 2 questions.', 'If you cannot go on: type the block number and the first error line (no names) below, then select "It failed". The app steps are then skipped.'); Url = 'https://make.apps.appsplatform.us/'; UrlConfig = '90161Z-app-portal.txt'; Marker = '90161Z-T21-app-built.txt'; Estimate = 900; DoneText = 'Done: app built'; DoneLog = 'Confirmed by you: app built.'; Makes = @(@{ kind = 'app'; name = '90161Z T21 Probe r1 (Power Apps, 1 screen)' }); After = @('T21 Import the probe solution r1'); Optional = $false; Help = 'Send the results as they are; the error line tells the next build which block to fix.'; Answers = @(@{ Key = 'app-blocks'; Prompt = 'Which block numbers pasted as code with no error? For example 1 2 3 4 5 6. Type 0 for none.'; Kind = 'text'; Choices = @() }, @{ Key = 'app-minutes'; Prompt = 'About how many minutes did this step take?'; Kind = 'text'; Choices = @() }) }
$steps += @{ Name = 'T21 App tests r1'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You use the test app: 2 buttons, 1 search, 1 look at the draft, and you sign 1 fake PDF and attach it. Tests T2, T4, T7, T8 and T10. About 10 minutes (estimate).'; Kind = 'guide'; Guide = @('1. In Power Apps select Play (the triangle, top right, or F5).', '2. Select the button "T4 a". A green line must say the row was written.', '3. Select the button "T4 b, T7 b, T8". A line must say the flow started.', '4. In the search box type the first 3 letters of any last name, then select "T7 a: search". The line under it shows counts only.', '5. Look at the PDF viewer and at the image beside it. Remember which of them shows the fake draft.', '6. In File Explorer open your OneDrive folder RADE\90-161.Z\T21 and open 90161Z-T21-fake-sign-r1.pdf.', '7. In Acrobat select All tools > Use a certificate > Digitally sign, draw a box and sign with your CAC.', '8. Save the signed file in the same folder with -signed at the end of its name.', '9. In the app form: type T10 in Title if it is empty. Select "Attach file", choose the signed PDF, select "T10: submit the form".', '10. Return to RADE, select "Done: tested" and answer the 3 questions.', 'If a button shows a red line: go on with the next step, and type the button name and the first words in the last answer.'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-app-tested.txt'; Estimate = 600; DoneText = 'Done: tested'; DoneLog = 'Confirmed by you: tested.'; Makes = @(); After = @('T21 Build the test app r1'); Optional = $false; Help = ''; Answers = @(@{ Key = 't2-view'; Prompt = 'What showed the fake draft in the app?'; Kind = 'pick'; Choices = @('PDF viewer and image', 'PDF viewer only', 'Image only', 'Neither') }, @{ Key = 't10-signed'; Prompt = 'Could you sign the fake PDF with your CAC and attach it?'; Kind = 'yesno'; Choices = @() }, @{ Key = 'app-notes'; Prompt = 'Did a button show a red line? Type the button and the first words (no names or addresses), or none.'; Kind = 'text'; Choices = @() }) }
$steps += @{ Name = 'T21 Second person r1'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Test T4. A second person with only Read on the test site opens the app and selects 2 buttons (about 5 minutes, estimate). If nobody is free today, select Skip: T4 is then not run.'; Kind = 'guide'; Guide = @('1. In Power Apps select Apps, select the three dots beside "90161Z T21 Probe r1", then Share.', '2. Add the second person as User (not Co-owner), select Share, and send that person the app link (Details > Web link).', '3. The person opens the link, selects Allow if asked, then selects the button "T4 a" and then the button "T4 b, T7 b, T8".', '4. Ask what the lines said (written, started, or refused).', '5. Return to RADE, select "Done: second person" and answer the question.', 'If the person cannot open the app: type the first line of what the person sees (no names) below, then select "It failed".'); Url = 'https://make.apps.appsplatform.us/'; UrlConfig = '90161Z-app-portal.txt'; Marker = '90161Z-T21-second-person.txt'; Estimate = 300; DoneText = 'Done: second person'; DoneLog = 'Confirmed by you: second person.'; Makes = @(); After = @('T21 Build the test app r1'); Optional = $false; Help = ''; Answers = @(@{ Key = 't4-second'; Prompt = 'What did the second person see?'; Kind = 'pick'; Choices = @('Both buttons worked', 'Only T4 a worked', 'Only the flow button worked', 'Neither worked') }) }
$steps += @{ Name = 'T21 Read the app tests r1'; Dir = 'T21'; File = '90161Z-T21-probe-r1.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 15; Args = '-Part App'; Note = 'Signs in (CAC) and reads the rows the app and its flow wrote. One PASSED or FAILED line for T4, T7, T8 and T10: field names and counts only. About 3 minutes (estimate).'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 180; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 App tests r1'); Optional = $false; Help = 'Send the results as they are.' }
$steps += @{ Name = 'T21 Remove the probe list and library r1'; Dir = 'T21'; File = '90161Z-T21-probe-r1.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 10; Args = '-Part Clean'; Note = 'Signs in (CAC). Moves the list "90161Z Probe" and the library "90161Z Probe Files" to the site Recycle Bin (restorable for 93 days). Removes nothing else. About 1 minute (estimate).'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Make the probe list and library r1'); Optional = $false; Help = 'Send the results as they are. The step can be run again.' }
$steps += @{ Name = 'T21 Remove the probe solutions and app r1'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You delete what the round made outside the site: up to 3 solutions, 1 app and 1 OneDrive folder. About 4 minutes (estimate).'; Kind = 'guide'; Guide = @('1. Select "Open in browser". In Power Automate select Solutions.', '2. For "90-161.Z probe", "90-161.Z probe Word" and "90-161.Z probe Mail", if listed: select the three dots > Delete from this environment.', '3. In Power Apps select Apps, the three dots beside "90161Z T21 Probe r1", then Delete.', '4. In OneDrive (web), delete the folder "90161Z-probe" if it is there.', '5. In Outlook, delete the test e-mails whose subject starts with "[TEST] 90161Z T9" (up to 4).', '6. Return to RADE and select "Done: removed".', 'If something does not delete: type its name and the first line of the message, then select "It failed".'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-removed.txt'; Estimate = 240; DoneText = 'Done: removed'; DoneLog = 'Confirmed by you: removed.'; Makes = @(); After = @(); Optional = $false; Help = '' }
